bsc-fleet() { r="${BSC_FLEET_ROSTER:-$PWD/fleet.roster.tsv}"; l="${BSC_COORD_LOG:-}"; if [ ! -f "$r" ]; then echo "bsc-fleet: no roster at $r (run from the project hub while a fleet is live)"; return 1; fi; printf 'roster: %s\n' "$r"; printf 'written %s - this is the LAUNCH MANIFEST; STATE is coord.log activity, NOT process liveness (use `bsc fleet`)\n' "$(date -r "$r" '+%Y-%m-%d %H:%M' 2>/dev/null || echo '?')"; printf 'PANE   STREAM             REPO                       BRANCH           ROLE     STATE\n'; awk -F'\t' -v LOG="$l" 'BEGIN { if (LOG != "") { while ((getline ln < LOG) > 0) { split(ln, a, "\t"); k=a[3]; if (k=="blocked"||k=="waiting"||k=="ask"||k=="woke"||k=="maintain") { st[a[2]]=k; on[a[2]]=(k=="blocked"||k=="ask")?a[4]:"" } } close(LOG) } } { s=st[$1]; if (s=="") s="-"; if (s=="woke") s="active"; if (s=="maintain") s="maintenance"; ex=(on[$1]!="")?" -> " on[$1]:""; printf "%-6s %-18s %-26s %-16s %-8s %s%s\n", $1, $2, $3, $4, $5, s, ex }' "$r"; }
